SELECT sum(1) AS sample_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh" FROM comstock_amy2018_r2_2025_md_agg_by_state_and_county_parquet AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND (bs.bldg_id, bs.county, bs.state) IN ((46369, 'G0800150', 'CO'), (46369, 'G0800190', 'CO'), (46369, 'G0800370', 'CO'), (46369, 'G0800490', 'CO'), (46369, 'G0800510', 'CO'), (46369, 'G0800930', 'CO'), (46369, 'G0801050', 'CO'), (46369, 'G0801070', 'CO'), (46369, 'G0801130', 'CO'), (46369, 'G0801170', 'CO'), (46370, 'G0800190', 'CO'), (46370, 'G0800370', 'CO'), (46370, 'G0800490', 'CO'), (46370, 'G0800510', 'CO'), (46370, 'G0800810', 'CO'), (46370, 'G0800930', 'CO'), (46370, 'G0801050', 'CO'), (46370, 'G0801070', 'CO'), (46370, 'G0801110', 'CO'), (46370, 'G0801130', 'CO')) AND bs.state = 'CO'